import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, of, catchError } from 'rxjs';
import { delay, map } from 'rxjs/operators';
import { SafeHtml } from '@angular/platform-browser';
import { ErrorHandlingService } from './error-handling.service';
import { AppConfigService } from './app-config.service';

export interface ChatMessage {
    from: 'user' | 'bot';
    text: string | SafeHtml;
    timestamp: string;
}

export interface ChatThread {
    thread_id: string;
    title?: string;
    timestamp: string;
    messages: ChatMessage[];
}

export interface PaymentStatus {
    paid: boolean;
}

export interface IsPremium {
    is_premium: boolean;
}

@Injectable({ providedIn: 'root' })
export class LawGptService {
    private appConfigService = inject(AppConfigService);
    private miniApiUrl = `${this.appConfigService.apiUrl}/lawgpt_mini.php`;
    private premiumApiUrl = `${this.appConfigService.apiUrl}/lawgpt_premium.php`;
    private historyapiUrl = `${this.appConfigService.apiUrl}/lawgpt-history.php`;
    private isPremiumApiUrl = `${this.appConfigService.apiUrl}/is_premium.php`;
    private paymentStatusApiUrl = `${this.appConfigService.apiUrl}/offline-payment-status.php`;
    private hasUsedPremiumTrialUrl = `${this.appConfigService.apiUrl}/has_used_premium_trial.php`;
    private activatePremiumTrialUrl = `${this.appConfigService.apiUrl}/try_premium.php`;

    private http = inject(HttpClient);
    private errorHandlingService = inject(ErrorHandlingService);

    getConversationHistory(userId: number): Observable<ChatThread[]> {
        return this.http
            .get<ChatThread[]>(`${this.historyapiUrl}?user_id=${userId}`)
            .pipe(
                catchError((error) => this.errorHandlingService.handleError<ChatThread[]>(error))
            );
    }

    createNewThread(): ChatThread {
        return {
            thread_id: (Math.random() * 1000000).toFixed(0),
            title: 'New Conversation',
            timestamp: new Date().toISOString(),
            messages: [
                {
                    from: 'bot',
                    text: "Welcome! I'm LawGPT. Feel free to ask your questions.",
                    timestamp: new Date().toISOString(),
                },
            ],
        };
    }

    postToPhpApi(
        messages: ChatMessage[],
        threadId: string,
        userId: number,
        isPremium: boolean
    ): Observable<{ response?: string; message_count_today?: number; error?: string }> {
        const apiUrl = isPremium ? this.premiumApiUrl : this.miniApiUrl;
        const headers = new HttpHeaders({ 'Content-Type': 'application/json' });
        const body = { thread_id: threadId, user_id: userId, conversation: messages.slice(-3) };
        return this.http
            .post<{ response?: string; message_count_today?: number; error?: string }>(apiUrl, body, { headers })
            .pipe(
                catchError((error) =>
                    this.errorHandlingService.handleError<{ response?: string; message_count_today?: number; error?: string }>(error)
                )
            );
    }

    getPaymentStatus(userId: number): Observable<PaymentStatus> {
        return this.http
            .get<PaymentStatus>(`${this.paymentStatusApiUrl}?user_id=${userId}`)
            .pipe(
                catchError((error) => this.errorHandlingService.handleError<PaymentStatus>(error))
            );
    }

    getIsPremium(userId: number): Observable<IsPremium> {
        return this.http
            .post<{ success: boolean; is_premium: boolean }>(this.isPremiumApiUrl, { user_id: userId })
            .pipe(
                map(res => ({ is_premium: res.is_premium })),
                catchError((error) => this.errorHandlingService.handleError<IsPremium>(error))
            );
    }

    uploadPaymentProof(file: File, userId: number, remarks: string): Observable<any> {
        const formData = new FormData();
        formData.append('receipt', file);
        formData.append('user_id', userId.toString());
        formData.append('remarks', remarks);
        return this.http.post(`${this.appConfigService.apiUrl}/upload_payment.php`, formData);
    }

    uploadDoc(formData: FormData): Observable<any> {
        return this.http.post(`${this.appConfigService.apiUrl}/ai_doc.php`, formData);
    }

    hasUsedPremiumTrial(userId: number): Observable<{ success: boolean, has_used_trial: boolean }> {
        const headers = new HttpHeaders({ 'Content-Type': 'application/json' });
        const body = { user_id: userId };
        return this.http.post<{ success: boolean, has_used_trial: boolean }>(this.hasUsedPremiumTrialUrl, body, { headers })
            .pipe(
                catchError((error) => this.errorHandlingService.handleError<{ success: boolean, has_used_trial: boolean }>(error))
            );
    }

    activatePremiumTrial(userId: number): Observable<{ success: boolean, message: string }> {
        const headers = new HttpHeaders({ 'Content-Type': 'application/json' });
        const body = { user_id: userId };
        return this.http.post<{ success: boolean, message: string }>(this.activatePremiumTrialUrl, body, { headers })
            .pipe(
                catchError((error) => this.errorHandlingService.handleError<{ success: boolean, message: string }>(error))
            );
    }
}
