import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { ChatThread, LawGptService } from '../chatbot.service';

declare const bootstrap: any;
@Component({
  selector: 'app-chatbot',
  templateUrl: './chatbot.component.html',
  styleUrls: ['./chatbot.component.scss']
})
export class ChatbotComponent implements OnInit {
  conversationThreads: ChatThread[] = [];
  currentThread: ChatThread | null = null;
  showLoginPrompt = false;
  showPaymentPrompt: boolean = false;
  isPremium = false;
  isCheckingPremium = false;
  showTrialButton = false;
  userId = Number(localStorage.getItem('user_id')) || 0;
  uploadStatus: string = '';
  remarks: string = '';  // New property for remarks input

  @ViewChild('fileInput') fileInput!: ElementRef<HTMLInputElement>;

  constructor(private lawGptService: LawGptService) { }

  ngOnInit(): void {
    if (this.userId === 0) {
      this.showLoginPrompt = true;
    } else {
      this.isCheckingPremium = true;
      this.lawGptService.getIsPremium(this.userId).subscribe({
        next: status => {
          this.isPremium = status.is_premium;
          this.isCheckingPremium = false;
          if (this.isPremium) {
            this.loadConversationHistory();
          } else {
            this.handleNonPremiumUser();
          }
        },
        error: () => {
          this.isCheckingPremium = false;
          this.handleNonPremiumUser();
        }
      });
    }
  }

  handleNonPremiumUser(): void {
    this.lawGptService.hasUsedPremiumTrial(this.userId).subscribe(trialStatus => {
      if (trialStatus.success && !trialStatus.has_used_trial) {
        this.showTrialButton = true;
      }
    });

    this.lawGptService.getPaymentStatus(this.userId).subscribe(paymentStatus => {
      if (!paymentStatus.paid) {
        this.showPaymentPrompt = true;
      } else {
        this.loadConversationHistory();
      }
    });
  }

  loadConversationHistory(): void {
    this.lawGptService.getConversationHistory(this.userId).subscribe(threads => {
      this.conversationThreads = threads;
      this.currentThread = this.lawGptService.createNewThread();
      this.conversationThreads.unshift(this.currentThread);
    });
  }

  handleThreadSelected(thread: ChatThread) {
    this.currentThread = thread;
  }

  startNewThread() {
    const newThread = this.lawGptService.createNewThread();
    this.conversationThreads.unshift(newThread);
    this.currentThread = newThread;
  }

  login(): void {
    window.location.href = '/login';
  }

  availCourse(): void {
    window.location.href = '/home/courses';
  }

  activateTrial(): void {
    this.lawGptService.activatePremiumTrial(this.userId).subscribe({
      next: (res) => {
        if (res.success) {
          alert('Premium trial activated for one day! The page will now reload.');
          window.location.reload();
        } else {
          alert('There was an issue activating your trial. Please try again later.');
        }
      },
      error: (err) => {
        const errorMessage = err.error?.error || 'An unknown error occurred.';
        alert(`Error: ${errorMessage}`);
      }
    });
  }

  uploadProof(): void {
    const file = this.fileInput.nativeElement.files?.[0];
    if (!file) {
      this.uploadStatus = 'Please select a file.';
      return;
    }

    this.lawGptService.uploadPaymentProof(file, this.userId, this.remarks).subscribe({
      next: (res: any) => {
        if (res.success) {
          this.uploadStatus = 'Proof uploaded successfully! Awaiting admin approval.';
          // Optionally close modal after delay
          setTimeout(() => {
            const modalElement = document.getElementById('upgradeModal');
            if (modalElement) {
              const modal = bootstrap.Modal.getInstance(modalElement);
              modal?.hide();
            }
          }, 3000);
        } else {
          this.uploadStatus = `Error: ${res.error}`;
        }
      },
      error: () => {
        this.uploadStatus = 'Upload failed. Please try again.';
      }
    });
  }
}