import { Component, OnInit, OnDestroy } from '@angular/core';
import { ErrorHandlingService, AppError } from './error-handling.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-error-alert',
  template: `
    <div *ngIf="error" class="alert alert-danger alert-dismissible fade show" role="alert">
      <h4 class="alert-heading">Error {{ error.status }}</h4>
      <p><strong>Message:</strong> {{ error.message }}</p>
      <p *ngIf="error.code"><strong>Code:</strong> {{ error.code }}</p>
      <p *ngIf="error.url"><strong>URL:</strong> {{ error.url }}</p>
      <p *ngIf="error.method"><strong>Method:</strong> {{ error.method }}</p>
      <div *ngIf="error.responseBody">
        <strong>Server Response:</strong>
        <pre class="mt-2 p-2 bg-light border rounded">{{ error.responseBody }}</pre>
      </div>
      <div *ngIf="error.headers">
        <strong>Response Headers:</strong>
        <pre class="mt-2 p-2 bg-light border rounded">{{ error.headers }}</pre>
      </div>
      <button type="button" class="btn-close" aria-label="Close" (click)="clearError()"></button>
    </div>
  `,
  styles: [
    `
      .alert {
        position: fixed;
        top: 20px;
        right: 20px;
        z-index: 1000;
        max-width: 600px;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
      }
      pre {
        white-space: pre-wrap;
        max-height: 200px;
        overflow-y: auto;
        font-size: 0.9rem;
      }
    `,
  ],
})
export class ErrorAlertComponent implements OnInit, OnDestroy {
  error: AppError | null = null;
  private subscription: Subscription | null = null;

  constructor(private errorHandlingService: ErrorHandlingService) { }

  ngOnInit() {
    this.subscription = this.errorHandlingService.error$.subscribe((error) => {
      this.error = error;
    });
  }

  ngOnDestroy() {
    this.subscription?.unsubscribe();
  }

  clearError() {
    this.errorHandlingService.clearError();
  }
}