import {
  Component, OnInit, OnDestroy,
  ViewChild, ElementRef,
  Input,
  OnChanges,
  SimpleChanges
} from '@angular/core';
import { ExamQuestion } from '../exam';
import { ExamService } from '../exam.service';

@Component({
  selector: 'app-exam',
  templateUrl: './exam.component.html',
  styleUrls: ['./exam.component.scss']
})
export class ExamComponent implements OnInit, OnDestroy {
  @ViewChild('questionCard') questionCard!: ElementRef<HTMLDivElement>;

  private _examId!: number;
  @Input()
  set examId(val: string | number) {
    const id = Number(val);
    if (!isNaN(id) && id >= 0 && id !== this._examId) {
      this._examId = id;
      this.loadExamData();
    }
  }
  get examId(): number { return this._examId; }

  userId = Number(localStorage.getItem('user_id')) || 0;

  loadingExam = true;
  loadingFeedback = false;

  totalExamTimeSeconds = 0;
  remainingTimeSeconds = 0;
  timerInterval: any;

  questions: ExamQuestion[] = [];
  private pendingQueue: number[] = [];

  currentQuestionIndex = -1;
  currentQuestion: ExamQuestion | null = null;
  userAnswer = '';
  isFeedbackPhase = false;
  currentFeedback = '';
  currentScore: number | null = null;

  showSummary = false;
  averageScore = 0;

  showLoginPrompt = false;

  unansweredCount = 0;
  currentUnansweredPosition = 0;

  constructor(private examService: ExamService) { }

  ngOnInit(): void {
    this.checkUserLogin();
  }

  ngOnDestroy(): void {
    this.clearTimer();
  }

  private checkUserLogin(): void {
    if (this.userId === 0) {
      this.showLoginPrompt = true;
      this.loadingExam = false;
    }
  }

  private loadExamData(): void {
    if (this.userId === 0) {
      this.showLoginPrompt = true;
      this.loadingExam = false;
      return;
    }

    this.loadingExam = true;
    this.showSummary = false;

    this.examService.fetchExamState(this.examId, this.userId)
      .subscribe({
        next: (state) => {
          this.questions = state.questions;
          this.totalExamTimeSeconds = state.totalExamTimeSeconds;
          this.remainingTimeSeconds = state.remainingTimeSeconds;

          if (this.remainingTimeSeconds <= 0) {
            return this.showSummaryPage();
          }

          // Build queue of unanswered questions
          this.pendingQueue = this.questions
            .map((q, i) => ({ question: q, index: i }))
            .filter(({ question }) => !question.answer || question.answer.trim() === '')
            .map(({ index }) => index);
          this.unansweredCount = this.pendingQueue.length;

          // If all questions have feedback, go to summary
          const allQuestionsAnswered = this.questions.every(q => q.feedback && q.feedback.trim() !== '');
          if (allQuestionsAnswered) {
            return this.showSummaryPage();
          }

          this.loadingExam = false;
          this.nextQuestion();
        },
        error: (err) => {
          console.error('Error loading exam:', err);
          this.loadingExam = false;
        }
      });
  }

  // private startTimer(): void {
  //   this.clearTimer();
  //   this.timerInterval = setInterval(() => {
  //     if (this.remainingTimeSeconds > 0 && !this.isFeedbackPhase) {
  //       this.remainingTimeSeconds--;
  //       if (this.remainingTimeSeconds === 0) {
  //         this.showSummaryPage();
  //       }
  //     }
  //   }, 1000);
  // }

  private clearTimer(): void {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
  }

  get formattedRemainingTime(): string {
    const m = Math.floor(this.remainingTimeSeconds / 60),
      s = this.remainingTimeSeconds % 60;
    return `${this.pad(m)}:${this.pad(s)}`;
  }
  private pad(n: number): string { return n < 10 ? '0' + n : '' + n; }

  canSubmit(): boolean {
    return this.userAnswer.trim().length > 0;
  }

  submitAnswer(): void {
    if (!this.canSubmit() || !this.currentQuestion || this.userId === 0) return;
    this.processAnswer(this.userAnswer.trim());
  }

  skipQuestion(): void {
    if (!this.currentQuestion || this.userId === 0) return;
    this.processSkip();
  }

  private processAnswer(answer: string): void {
    this.isFeedbackPhase = true;
    this.loadingFeedback = true;
    this.clearTimer();

    const qid = this.currentQuestion!.id,
      ts = new Date().toISOString();

    this.examService.submitAnswer(
      this.userId, this.examId, qid, answer, ts, this.remainingTimeSeconds
    ).subscribe({
      next: (res) => {
        this.currentQuestion!.answer = answer;
        this.currentQuestion!.feedback = res.feedback;
        this.currentQuestion!.score = res.score;

        this.currentFeedback = res.feedback;
        this.currentScore = res.score;
        this.loadingFeedback = false;
      },
      error: (err) => {
        console.error('Error submitting answer:', err);
        this.loadingFeedback = false;
      }
    });
  }

  private processSkip(): void {
    this.clearTimer();
    this.currentQuestion!.answer = '';
    this.nextQuestion();
  }

  moveToNextQuestion(): void {
    this.isFeedbackPhase = false;
    this.currentFeedback = '';
    this.currentScore = null;
    this.nextQuestion();
  }

  private nextQuestion(): void {
    const next = this.pendingQueue.shift();
    if (next === undefined) {
      this.showSummaryPage();
    } else {
      this.currentQuestionIndex = next;
      this.currentQuestion = this.questions[next];
      this.userAnswer = this.currentQuestion.answer || '';
      this.currentFeedback = this.currentQuestion.feedback || '';
      this.currentScore = this.currentQuestion.score;
      this.currentUnansweredPosition++;
      this.isFeedbackPhase = !!this.currentFeedback;
      // if (!this.isFeedbackPhase) {
      //   this.startTimer();
      // }
      setTimeout(() => this.questionCard?.nativeElement.focus(), 0);
    }
  }

  private showSummaryPage(): void {
    this.showSummary = true;
    this.clearTimer();
    const total = this.questions.reduce((acc, q) => acc + (q.score || 0), 0);
    this.averageScore = this.questions.length ? total / this.questions.length : 0;
  }

  login(): void {
    window.location.href = '/login';
  }
}