import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { ChatThread } from 'src/app/chatbot.service';

@Component({
  selector: 'app-chat-history',
  templateUrl: './chat-history.component.html',
  styleUrls: ['./chat-history.component.scss']
})
export class ChatHistoryComponent implements OnInit {
  @Input() threads: ChatThread[] = [];
  @Output() threadSelected = new EventEmitter<ChatThread>();

  selectedThread: ChatThread | null = null;

  constructor() { }

  ngOnInit(): void { }

  selectThread(thread: ChatThread) {
    this.selectedThread = thread;
    this.threadSelected.emit(thread); // emit the thread object
  }

  closeThread() {
    this.selectedThread = null;
  }
}