import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of, catchError } from 'rxjs';
import { delay } from 'rxjs/operators';
import { ExamStateResponse, AnswerResponse } from './exam';
import { ErrorHandlingService } from './error-handling.service';
import { AppConfigService } from './app-config.service';

@Injectable({ providedIn: 'root' })
export class ExamService {
  private appConfigService = inject(AppConfigService);
  private baseUrl = `${this.appConfigService.apiUrl}/exam.php`;

  private http = inject(HttpClient);
  private errorHandlingService = inject(ErrorHandlingService);

  fetchExamState(examId: number, userId: number): Observable<ExamStateResponse> {
    return this.http
      .post<ExamStateResponse>(this.baseUrl, {
        action: 'questions',
        examId,
        userId,
      })
      .pipe(
        catchError((error) => this.errorHandlingService.handleError<ExamStateResponse>(error))
      );
  }

  submitAnswer(
    userId: number,
    examId: number,
    questionId: number,
    answerContent: string,
    timestamp: string,
    remainingTime: number
  ): Observable<AnswerResponse> {
    return this.http
      .post<AnswerResponse>(this.baseUrl, {
        action: 'answer',
        userId,
        examId,
        questionId,
        answerContent,
        timestamp,
        remainingTime,
      })
      .pipe(
        catchError((error) => this.errorHandlingService.handleError<AnswerResponse>(error))
      );
  }
}