import { APP_INITIALIZER, DoBootstrap, Injector, NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { RouterModule, Routes } from '@angular/router';

import { AppRoutingModule } from './app-routing.module';
import { AppComponent } from './app.component';
import { ChatbotComponent } from './chatbot/chatbot.component';
import { createCustomElement } from '@angular/elements';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FormsModule } from '@angular/forms';
import { APP_BASE_HREF, CommonModule } from '@angular/common';
import { ExamComponent } from './exam/exam.component';
import { InlineLoaderComponent } from './loader/loader.component';
import { ChatWindowComponent } from './chatbot/chat-window/chat-window.component';
import { ChatHistoryComponent } from './chatbot/chat-history/chat-history.component';
import { PromptGuideComponent } from './chatbot/prompt-guide/prompt-guide.component';
import { LawgptPopupComponent } from './chatbot/popup/popup.component';
import { ErrorPageComponent } from './errorpage/errorpage.component';
import { HttpInterceptorService } from './http-interceptor.service';
import { ErrorAlertComponent } from './error-alert-component';
import { AppConfigService } from './app-config.service';

const routes: Routes = [
  { path: 'error', component: ErrorPageComponent },
  // Add other routes as needed
];

@NgModule({
  declarations: [
    AppComponent,
    ChatbotComponent,
    ExamComponent,
    InlineLoaderComponent,
    ChatWindowComponent,
    ChatHistoryComponent,
    PromptGuideComponent,
    LawgptPopupComponent,
    ErrorPageComponent,
    ErrorAlertComponent
  ],
  imports: [
    BrowserModule,
    AppRoutingModule,
    HttpClientModule,
    FormsModule,
    CommonModule,
    RouterModule.forRoot(routes),
  ],
  providers: [
    { provide: APP_BASE_HREF, useValue: '/' },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: HttpInterceptorService,
      multi: true,
    },
    {
      provide: APP_INITIALIZER,
      useFactory: (appConfigService: AppConfigService) => () => appConfigService.loadAppConfig(),
      deps: [AppConfigService],
      multi: true
    },
  ],
  exports: [
    InlineLoaderComponent,
  ],
  //bootstrap: [AppComponent]
})
export class AppModule implements DoBootstrap {
  constructor(private injector: Injector) { }

  ngDoBootstrap() {
    // Register chatbot widget
    const chatbotEl = createCustomElement(ChatbotComponent, { injector: this.injector });
    if (!customElements.get('chatbot-widget')) {
      customElements.define('chatbot-widget', chatbotEl);
    }

    // Register exam widget
    const examEl = createCustomElement(ExamComponent, { injector: this.injector });
    if (!customElements.get('app-exam-widget')) {
      customElements.define('app-exam-widget', examEl);
    }
  }
}
