import { Injectable } from '@angular/core';
import { Observable, throwError, BehaviorSubject } from 'rxjs';
import { HttpErrorResponse } from '@angular/common/http';

export interface AppError {
    message: string;
    code?: string;
    status: number;
    url?: string;
    method?: string;
    responseBody?: string;
    headers?: string;
}

@Injectable({
    providedIn: 'root',
})
export class ErrorHandlingService {
    private errorSubject = new BehaviorSubject<AppError | null>(null);
    error$ = this.errorSubject.asObservable();

    constructor() { }

    handleError<T>(error: any): Observable<never> {
        let errorMessage = 'An unexpected error occurred';
        let errorCode: string | undefined;
        let statusCode = 500;
        let url: string | undefined;
        let method: string | undefined;
        let responseBody: string | undefined;
        let headers: string | undefined;

        if (error instanceof HttpErrorResponse) {
            statusCode = error.status;
            url = error.url || 'Unknown URL';
            method = error?.name?.split(' ')[0] || 'Unknown Method';

            headers = JSON.stringify(
                error.headers?.keys().reduce((acc: { [key: string]: string }, key: string) => {
                    acc[key] = error.headers.get(key) || '';
                    return acc;
                }, {}),
                null,
                2
            ) || '{}';

            if (statusCode >= 200 && statusCode < 300) {
                // Handle cases where a 2xx status is incorrectly treated as an error
                errorMessage = `Unexpected success response treated as error (status ${statusCode})`;
                responseBody = JSON.stringify(error.error, null, 2) || error.statusText || undefined;
            } else if (error.error && typeof error.error === 'object') {
                // Handle raw error objects (e.g., { message: string, code?: string })
                errorMessage = error.error.message || error.statusText || errorMessage;
                errorCode = error.error.code;
                responseBody = JSON.stringify(error.error, null, 2);
            } else if (typeof error.error === 'string') {
                // Handle raw error strings
                errorMessage = error.error || error.statusText || errorMessage;
                responseBody = error.error;
            } else {
                errorMessage = error.statusText || errorMessage;
                responseBody = JSON.stringify(error.error, null, 2) || undefined;
            }
        } else if (error instanceof Error) {
            errorMessage = `Client error: ${error.message}`;
            responseBody = JSON.stringify(error, null, 2) || undefined;
        } else {
            errorMessage = error.message || errorMessage;
            responseBody = JSON.stringify(error, null, 2) || undefined;
        }

        const appError: AppError = {
            message: errorMessage,
            code: errorCode,
            status: statusCode,
            url,
            method,
            responseBody,
            headers,
        };

        this.errorSubject.next(appError);

        return throwError(() => new Error(errorMessage));
    }

    clearError(): void {
        this.errorSubject.next(null);
    }
}