import {
  Component,
  ElementRef,
  Input,
  OnDestroy,
  OnInit,
  ViewChild
} from '@angular/core';
import { LawGptService, ChatMessage } from '../../chatbot.service';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

@Component({
  selector: 'app-chat-window',
  templateUrl: './chat-window.component.html',
  styleUrls: ['./chat-window.component.scss']
})
export class ChatWindowComponent implements OnInit, OnDestroy {
  userId = Number(localStorage.getItem('user_id')) || 0;

  @Input() threadId!: string;
  @Input() messages: ChatMessage[] = [];
  @Input() isPremium: boolean = false;

  @ViewChild('chatScroll') chatScroll?: ElementRef<HTMLDivElement>;
  @ViewChild('inputRef') inputRef?: ElementRef<HTMLTextAreaElement>;
  @ViewChild('fileUploadInput') fileUploadInput!: ElementRef<HTMLInputElement>;

  userInput = '';
  isLoading = false;
  dailyLimitReached = false;
  thinkingTimer: number = 0;
  timerInterval: any;
  isProcessingFile = false;  // New flag to disable chat during file upload

  constructor(
    private lawGptService: LawGptService,
    private sanitizer: DomSanitizer
  ) { }

  ngOnInit(): void {
    setTimeout(() => this.scrollToBottom(), 0);
  }

  ngOnDestroy() {
    this.stopTimer();
  }

  onEnter(e: any) {
    if (!e.shiftKey) {
      e.preventDefault();
      this.onSend();
    }
  }

  onSend() {
    const text = this.userInput.trim();
    if (!text || this.isLoading || this.isProcessingFile || (!this.isPremium && this.dailyLimitReached)) return;

    this.isLoading = true;
    this.thinkingTimer = 0;
    this.startTimer();

    // Create & push user text message
    const userMsg: ChatMessage = {
      from: 'user',
      text: text,
      timestamp: new Date().toISOString()
    };
    this.messages.push(userMsg);
    this.scrollToBottom();

    // Prepare context (text only)
    const context = this.messages.slice(-2);
    this.sendToApi(context);
  }

  private sendToApi(context: any[]) {
    this.lawGptService
      .postToPhpApi(context, this.threadId, this.userId, this.isPremium)
      .subscribe({
        next: (res) => {
          this.stopTimer();
          if (res.response) {
            let responseText = res.response;
            const messageCount = res.message_count_today ?? 0;

            if (this.isPremium) {
              const html = marked.parse(responseText);
              responseText = DOMPurify.sanitize(html as string);
            }

            if (!this.isPremium && messageCount >= 25) {
              this.dailyLimitReached = true;
              responseText += `
                <div class="alert alert-danger mt-3" role="alert">
                  <i class="fas fa-exclamation-circle me-2"></i>
                  Daily limit of 25 requests reached. Please try again tomorrow.
                </div>`;
            } else if (!this.isPremium && messageCount === 24) {
              responseText += `
                <div class="alert alert-warning mt-3" role="alert">
                  <i class="fas fa-exclamation-triangle me-2"></i>
                  You have one remaining request for today. Use it wisely!
                </div>`;
            }

            const safe: SafeHtml = this.sanitizer.bypassSecurityTrustHtml(responseText);
            const botMsg: ChatMessage = {
              from: 'bot',
              text: safe,
              timestamp: new Date().toISOString()
            };
            this.messages.push(botMsg);
            this.scrollToBottom();

            this.isLoading = false;
            this.userInput = '';
            if (this.inputRef) this.inputRef.nativeElement.focus();
          } else {
            this.pushError('No response from server.');
          }
        },
        error: (err) => {
          this.pushError(`API error: ${err.message || 'Failed to get response'}`);
        }
      });
  }

  onUploadDoc() {
    if (!this.isPremium) return;

    const input = this.fileUploadInput.nativeElement;
    input.click();
  }

  onDocSelected(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const file = input.files[0];
      if (file.size > 20 * 1024 * 1024) {
        this.pushError('File too large (max 20MB).');
        return;
      }
      if (!['text/plain', 'application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'image/jpeg', 'image/png'].includes(file.type)) {
        this.pushError('Only TXT, PDF, DOCX, JPG, PNG supported.');
        return;
      }

      this.isProcessingFile = true;  // Disable chatting
      this.messages.push({
        from: 'bot',
        text: this.sanitizer.bypassSecurityTrustHtml('<div class="alert alert-info animate__animated animate__fadeIn"><i class="fas fa-spinner fa-spin me-2"></i>Processing file... Please wait.</div>'),
        timestamp: new Date().toISOString()
      });
      this.scrollToBottom();

      const formData = new FormData();
      formData.append('doc_file', file);
      formData.append('user_id', this.userId.toString());

      this.lawGptService.uploadDoc(formData).subscribe(res => {
        this.isProcessingFile = false;  // Re-enable chatting

        if (res.success) {
          this.userInput += `\nExtracted text: ${res.extracted_text}`;
          this.messages.push({
            from: 'bot',
            text: this.sanitizer.bypassSecurityTrustHtml('<div class="alert alert-success animate__animated animate__fadeIn">File converted to text and appended to your input.</div>'),
            timestamp: new Date().toISOString()
          });
        } else {
          this.messages.push({
            from: 'bot',
            text: this.sanitizer.bypassSecurityTrustHtml(`
              <div class="alert alert-danger animate__animated animate__fadeIn">
                File conversion failed: ${res.extracted_text}<br>
                Debug: ${JSON.stringify(res.debug)}
              </div>
            `),
            timestamp: new Date().toISOString()
          });
        }
        input.value = '';
        this.scrollToBottom();
      });
    }
  }

  private pushError(message: string) {
    this.messages.push({
      from: 'bot',
      text: this.sanitizer.bypassSecurityTrustHtml(`
        <div class="alert alert-danger animate__animated animate__fadeIn">
          <i class="fas fa-exclamation-circle me-2"></i>${message}
        </div>
      `),
      timestamp: new Date().toISOString()
    });
    this.isLoading = false;
    this.stopTimer();
    this.scrollToBottom();
  }

  private startTimer() {
    this.timerInterval = setInterval(() => {
      this.thinkingTimer++;
    }, 1000);
  }

  private stopTimer() {
    clearInterval(this.timerInterval);
    this.thinkingTimer = 0;
  }

  private scrollToBottom() {
    if (this.chatScroll?.nativeElement) {
      const el = this.chatScroll.nativeElement;
      el.scrollTop = el.scrollHeight;
    }
  }
}