import { Component, EventEmitter, OnInit, Output } from '@angular/core';

@Component({
  selector: 'app-lawgpt-popup',
  templateUrl: './popup.component.html',
  styleUrls: ['./popup.component.scss']
})
export class LawgptPopupComponent implements OnInit {
  @Output() closed = new EventEmitter<void>();
  pulse = false;
  show = false;

  ngOnInit(): void {
    // Only show if not already dismissed this session
    if (!sessionStorage.getItem('lawgpt_popup_dismissed')) {
      this.show = true;
    }
  }

  dismiss() {
    this.show = false;
    sessionStorage.setItem('lawgpt_popup_dismissed', '1');
    this.closed.emit();
  }
}